    expect(hiddenCat).toBeDefined();
    // If the category has a hidden flag, ensure it's true
    if (hiddenCat && 'hidden' in hiddenCat) {
      // @ts-ignore
      expect(hiddenCat.hidden).toBe(true);
    }

    // attempt to delete the in‑use category (should be refused)
